import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Login.css';

const Login = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleLogin = (e) => {
    e.preventDefault();

    // Dummy login logic for demo (replace with real auth API)
    if (email && password) {
      localStorage.setItem('token', 'sampleToken');
      const role = 'doctor'; // 🔁 Replace this with actual role from API response

      if (role === 'doctor') navigate('/dashboard/doctor');
      else if (role === 'patient') navigate('/dashboard/patient');
      else if (role === 'hospital') navigate('/dashboard/hospital');
    } else {
      alert('Please fill in all fields');
    }
  };

  return (
    <div className="container">
      {/* Left: Login Form */}
      <div className="login-section">
        <div className="login-card">
          <h2>Login to MediVault</h2>
          <form onSubmit={handleLogin}>
            <input
              type="email"
              placeholder="Email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
            <input
              type="password"
              placeholder="Password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <button type="submit" className="login-btn">Login</button>
            <div className="links">
              <a href="#">Forgot Password?</a><br />
              Don’t have an account? <a href="/register">Register here</a>
            </div>
          </form>
        </div>
      </div>

      {/* Right: Welcome Section */}
      <div className="welcome-section">
        <div className="welcome-content">
          <h1>Welcome to <span>MediVault</span></h1>
          <p>Your health, organized and always accessible.</p>
        </div>
        <div className="blob"></div>
        <div className="blob"></div>
        <div className="blob"></div>
      </div>
    </div>
  );
};

export default Login;
